namespace MathComposer.Core;

/// <summary>Identifies an accent glyph and placement.</summary>
public enum MathAccentKind
{
    /// <summary>An acute accent.</summary>
    Acute,

    /// <summary>A grave accent.</summary>
    Grave,

    /// <summary>A circumflex accent.</summary>
    Hat,

    /// <summary>A check accent.</summary>
    Check,

    /// <summary>A breve accent.</summary>
    Breve,

    /// <summary>A tilde accent.</summary>
    Tilde,

    /// <summary>A bar accent.</summary>
    Bar,

    /// <summary>A dot accent.</summary>
    Dot,

    /// <summary>A double-dot accent.</summary>
    DoubleDot,

    /// <summary>A triple-dot accent.</summary>
    TripleDot,

    /// <summary>A vector arrow accent.</summary>
    Vector
}
